// src/components/CompanyForm.js
import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import "../index.css";

const DOMAINS = [
  "Healthcare",
  "Information Technology",
  "Software",
  "SaaS",
  "Finance",
  "Education",
  "E-commerce",
  "Marketing",
  "Manufacturing",
  "Retail",
  "Hospitality",
  "Transportation",
  "Telecommunications",
  "Real Estate",
  "Energy",
  "Energy & Utilities",
  "Automotive",
  "Agriculture",
  "Pharmaceuticals",
  "Media",
  "Media & Entertainment",
  "Entertainment",
  "Government",
  "Non-profit",
  "Legal",
  "Other",
  "Research & Development",
  "Cloud Computing",
  "Software Development",
  "Data Science",
  "Automation",
  "Web Development",
  "Mobile Apps",
  "AI & ML",
  "AI",
  "Cybersecurity"
];

const CompanyForm = () => {
  const navigate = useNavigate();
  const [formData, setFormData] = useState({
    company_name: "",
    company_description: "",
    country: "",
    city: "",
    company_size: "",
    domain: "", // new dropdown field
  });

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = (e) => {
    e.preventDefault();

    // get current user (if any)
    const cu = JSON.parse(localStorage.getItem("currentUser") || "null") || {};
    const email = cu.email || "";

    // Make a copy of form data and ensure user_email + user_id are usable for lookup
    const profileToSave = {
      ...formData,
      // if user_id left blank, store user email so Dashboard can match by email
      user_id: formData.user_id && String(formData.user_id).trim() !== "" ? String(formData.user_id) : email,
      // always store the creator email explicitly (reliable lookup field)
      user_email: email,
      id: Date.now()
    };

    // Save company profile locally
    const existing = JSON.parse(localStorage.getItem("companyProfiles") || "[]");
    existing.push(profileToSave);
    localStorage.setItem("companyProfiles", JSON.stringify(existing));

    // mark profile created and set role on currentUser so next login is deterministic
    localStorage.setItem("profileCreated", "true");
    const updatedUser = { ...cu, role: "company", email };
    localStorage.setItem("currentUser", JSON.stringify(updatedUser));

    alert("Company profile created!");
    navigate("/dashboard");
  };

  return (
    <div className="form-container">
      <h1 className="heading">SoftScale</h1>
      <div className="form-box">
        <h2>Company Admin Profile</h2>

        <form onSubmit={handleSubmit}>
          <input
            name="company_name"
            placeholder="Company Name"
            value={formData.company_name}
            onChange={handleChange}
            required
          />
          <textarea
            name="company_description"
            placeholder="Company Description"
            value={formData.company_description}
            onChange={handleChange}
            rows={4}
            style={{ width: "100%", padding: 10, borderRadius: 8, border: "1px solid #ccc", marginTop: 8 }}
          />

          {/* NEW: Domain dropdown */}
          <label style={{ display: "block", marginTop: 8, marginBottom: 6, color: "#333", fontSize: 14 }}>
            Company Domain
          </label>
          <select
            name="domain"
            value={formData.domain}
            onChange={handleChange}
            style={{ width: "100%", padding: 10, borderRadius: 8, border: "1px solid #ccc", background: "#fff" }}
            required
          >
            <option value="">Select domain</option>
            {DOMAINS.map((d) => (
              <option key={d} value={d}>
                {d}
              </option>
            ))}
          </select>

          <input
            name="country"
            placeholder="Country"
            value={formData.country}
            onChange={handleChange}
          />
          <input
            name="city"
            placeholder="City"
            value={formData.city}
            onChange={handleChange}
          />
          <input
            name="company_size"
            placeholder="Company Size (e.g., 50-200)"
            value={formData.company_size}
            onChange={handleChange}
          />

          <button type="submit" className="btn-primary" style={{ marginTop: 12 }}>
            Create Company
          </button>
        </form>
      </div>
    </div>
  );
};

export default CompanyForm;
